use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::kb_read;

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds maximum length".to_string(),
            });
        }

        let system = "You are a customer support assistant. Use the provided knowledge to answer the question. If you need more information, you may call the lookup tool.";

        let mut prompt = String::new();
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\n\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        match tool_llm::generate(system, &prompt) {
            Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
            Reply::Call(req) => {
                if req.tool != "lookup" {
                    return ResponseResult::Error(LlmError {
                        message: format!("unsupported tool requested: {}", req.tool),
                    });
                }

                let results = kb_read::lookup(&req.query);

                let mut follow_up_prompt = String::new();
                follow_up_prompt.push_str("Question: ");
                follow_up_prompt.push_str(&ctx.question);
                follow_up_prompt.push_str("\n\nLookup results for query \"");
                follow_up_prompt.push_str(&req.query);
                follow_up_prompt.push_str("\":\n");
                for r in &results {
                    follow_up_prompt.push_str("- ");
                    follow_up_prompt.push_str(r);
                    follow_up_prompt.push('\n');
                }

                match tool_llm::generate(system, &follow_up_prompt) {
                    Reply::Text(text) => ResponseResult::Ok(AgentResponse { text }),
                    Reply::Call(_) => ResponseResult::Error(LlmError {
                        message: "model requested a second tool call, which is not supported"
                            .to_string(),
                    }),
                }
            }
        }
    }
}

export!(Node);
